const PEXELS_IMAGES: Record<string, string> = {
  // Pexels doesn't have specific character images; we use a cinematic/film aesthetic placeholder
};

interface Props {
  personalityId: string;
  language: string;
}

export default function CinematicPersonaCard({ personalityId, language }: Props) {
  const { t } = useTranslation();
  const [showModal, setShowModal] = useState(false);
  const [showEnglish, setShowEnglish] = useState(false);

  const persona = PERSONAS[personalityId];
  if (!persona) return null;

  const isEn = language.startsWith('en') || showEnglish;
  const description = isEn ? persona.descriptionEn : persona.descriptionPt;

  const accentColor = (() => {
    if (!personalityId || personalityId.length < 3) return '#3b82f6';
    const sub = personalityId.charAt(2);
    const map: Record<string, string> = { A: '#f59e0b', B: '#8b5cf6', K: '#ef4444', X: '#3b82f6', D: '#FFFFFF', L: '#10b981' };
    return map[sub] || '#3b82f6';
  })();

  return (
    <>
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.5, delay: 0.25 }}
        className="mb-8"
      >
        <button
          onClick={() => setShowModal(true)}
          className="w-full text-left group relative rounded-3xl bg-white/40 dark:bg-gray-800/40 backdrop-blur-xl border border-white/60 dark:border-gray-700/60 shadow-2xl overflow-hidden p-6 hover:shadow-xl transition-all duration-300"
        >
          {/* Background glow */}
          <div
            className="absolute inset-0 opacity-0 group-hover:opacity-100 transition-opacity duration-300 rounded-3xl"
            style={{ background: `radial-gradient(ellipse at top right, ${accentColor}18, transparent 60%)` }}
          />
          <div className="absolute top-0 right-0 w-40 h-40 rounded-full blur-3xl opacity-20"
            style={{ background: accentColor }} />

          <div className="relative z-10 flex items-center gap-5">
            {/* Avatar placeholder */}
            <div
              className="flex-shrink-0 w-16 h-16 rounded-2xl flex items-center justify-center border-2 shadow-lg"
              style={{ borderColor: `${accentColor}60`, background: `${accentColor}20` }}
            >
              <User className="w-8 h-8" style={{ color: accentColor }} />
            </div>

            <div className="flex-1 min-w-0">
              <p className="text-xs font-semibold uppercase tracking-widest mb-0.5" style={{ color: accentColor }}>
                {isEn ? 'Your Persona' : 'Sua Persona'}
              </p>
              <h3 className="text-xl font-bold text-gray-900 dark:text-white truncate">
                {persona.name}
              </h3>
              <p className="text-sm text-gray-500 dark:text-gray-400 mt-1 line-clamp-2">
                {isEn ? persona.descriptionEn : persona.descriptionPt}
              </p>
            </div>

            <div
              className="flex-shrink-0 w-8 h-8 rounded-xl flex items-center justify-center opacity-60 group-hover:opacity-100 transition-opacity"
              style={{ background: `${accentColor}30` }}
            >
              <svg className="w-4 h-4" style={{ color: accentColor }} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
              </svg>
            </div>
          </div>
        </button>
      </motion.div>

      <AnimatePresence>
        {showModal && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-black/70 backdrop-blur-sm z-[9999] flex items-center justify-center p-4"
            onClick={() => setShowModal(false)}
          >
            <motion.div
              initial={{ scale: 0.9, opacity: 0, y: 20 }}
              animate={{ scale: 1, opacity: 1, y: 0 }}
              exit={{ scale: 0.9, opacity: 0, y: 20 }}
              transition={{ type: 'spring', stiffness: 300, damping: 25 }}
              onClick={e => e.stopPropagation()}
              className="relative w-full max-w-md rounded-3xl overflow-hidden shadow-2xl"
              style={{ background: 'rgba(10,10,20,0.92)', border: `1px solid ${accentColor}40` }}
            >
              {/* Top color band */}
              <div className="absolute top-0 inset-x-0 h-1" style={{ background: `linear-gradient(90deg, transparent, ${accentColor}, transparent)` }} />

              {/* Background glow */}
              <div className="absolute top-0 right-0 w-64 h-64 rounded-full blur-3xl opacity-10"
                style={{ background: accentColor }} />

              {/* Close button */}
              <button
                onClick={() => setShowModal(false)}
                className="absolute top-4 right-4 z-10 p-2 rounded-xl bg-white/10 hover:bg-white/20 transition-colors"
              >
                <X className="w-5 h-5 text-white" />
              </button>

              <div className="relative z-10 p-7">
                {/* Avatar */}
                <div className="flex justify-center mb-5">
                  <div
                    className="w-28 h-28 rounded-2xl flex items-center justify-center border-2 shadow-xl"
                    style={{ borderColor: `${accentColor}80`, background: `${accentColor}25` }}
                  >
                    <User className="w-14 h-14" style={{ color: accentColor }} />
                  </div>
                </div>

                {/* Essence badge */}
                <div className="flex justify-center mb-2">
                  <span
                    className="text-xs font-bold uppercase tracking-widest px-3 py-1 rounded-full"
                    style={{ background: `${accentColor}25`, color: accentColor, border: `1px solid ${accentColor}50` }}
                  >
                    {personalityId}
                  </span>
                </div>

                {/* Name */}
                <h2 className="text-2xl font-extrabold text-white text-center mb-4">
                  {persona.name}
                </h2>

                {/* Description */}
                <p className="text-gray-300 text-sm leading-relaxed text-center mb-6">
                  {description}
                </p>

              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </>
  );
}
